<?php
namespace App\Tests\Runtime;
use App\Runtime\{RuntimePurchaseItemAudit,RuntimeCiwErpQuery,RuntimeHttpException};
use PHPUnit\Framework\TestCase;
final class RuntimePurchaseItemAuditTest extends TestCase {
 public static function definition(): array {return ['entityCode'=>'proc_compra_itens_progress','primaryKey'=>'item_proc_compra_id','apiBinding'=>['sourceCode'=>'motor_progress_ciw_cadastros'],'apiSource'=>['responseContract'=>'sursum-programs'],'fields'=>['proc_compra_id'=>['dataType'=>'integer']]];}
 public static function endpoint(string $op): array{return ['method'=>'POST','url'=>'http://127.0.0.1:19910/med/web/SursumPrograms/ciw-cadastros','bodyTemplate'=>['resource'=>'proc_compra_itens','operation'=>$op],'requestContextFields'=>['proc_compra_id']];}
 public static function row(): array {return json_decode('{"item_proc_compra_id":11,"descricao":"Item teste","codigo_erp":"","qt_dias_producao":0,"vl_base_tributacao":0,"unid_medida":"MT","proc_compra_id":17,"qt_comprada":0,"vl_custo_dolar":0,"composicao":"","peso":"","largura":"","rolo":"","dt_prev_envio_desenhos":null,"dt_real_envio_desenhos":null,"log_aprov_so_ld":false,"dt_prev_recbto_so_ld":null,"dt_prev_aprov_so_ld":null,"dt_real_aprov_so_ld":null,"coloracao_id":0,"dt_maxima_producao":null,"dt_mostruario":null,"log_mostruario":false,"formato_amostra_id":0,"ind_producao_no_prazo":0,"ind_relat_semanal_producao":0,"ind_qualid_emb":0,"ind_laudo_antes_embarque":0,"ind_prod_conf_pi":0,"ind_rec_amostra_antes_emb":0,"ind_qt_conf_proforma":0,"ind_tamanho_pecas_correto":0,"observacao":"","dt_cheg_amostras_emb":null,"dt_termino_producao":null,"vl_cubagem":0,"dt_recbto_laudo":null,"dt_recbto_embalagem":null,"dt_real_recbto_so_ld":null,"dt_prev_termino_producao":null,"qt_dias_calc_so_ld":0,"shrinkage":"","ind_distr_custo":0,"vl_negociado":0,"item_estacao":0,"dt_item_certificacao":null}',true);}
 public static function data(): array {return self::row()+['row_stamp'=>str_repeat('A',64),'qt_alocada'=>0,'qt_saldo'=>0,'calc_gm'=>null];}
 public static function body(string $op='update'): array {return ['success'=>true,'committed'=>true,'data'=>$op==='delete'?[]:self::data(),'audit'=>['version'=>1,'source'=>'progress-transaction','resource'=>'itens-proc-compra','operation'=>$op,'recordId'=>11,'actor'=>['login'=>'real-user'],'before'=>$op==='create'?[]:self::row(),'after'=>$op==='delete'?[]:self::row(),'changes'=>[],'warnings'=>[]]];}
 public static function inspect(array $b,string $op='update'): array{return RuntimePurchaseItemAudit::inspect(self::definition(),self::endpoint($op),$b,$op,11,17,'real-user');}
 public function testFullPhysicalAndDtoContractsForEveryMutation():void {self::assertCount(46,self::row());self::assertCount(50,self::data());foreach(['create','update','delete']as $op){$b=self::body($op);$a=self::inspect($b,$op);self::assertTrue($a['metadata']['available']);self::assertSame($b['audit']['before'],$a['before']);self::assertSame($b['audit']['after'],$a['after']);self::assertSame(11,$a['metadata']['itemProcCompraId']);self::assertTrue(RuntimePurchaseItemAudit::dataRow(self::data()));}}
 public function testRejectsForgedIncompleteAndUncommittedEvidenceAtomically():void {foreach(['commit','actor','unknown','missing','stamp','projection','parent','decimal','bool','date','data']as $c){$b=self::body();switch($c){case 'commit':$b['committed']=false;break;case 'actor':$b['audit']['actor']['login']='browser';break;case 'unknown':$b['audit']['x']=1;break;case 'missing':unset($b['audit']['after']['peso']);break;case 'stamp':$b['audit']['after']['row_stamp']=str_repeat('A',64);break;case 'projection':$b['audit']['after']['qt_saldo']=0;break;case 'parent':$b['audit']['after']['proc_compra_id']=18;break;case 'decimal':$b['audit']['after']['qt_comprada']='1,5';break;case 'bool':$b['audit']['after']['log_mostruario']=1;break;case 'date':$b['audit']['after']['dt_mostruario']='2026-02-30';break;case 'data':unset($b['data']['calc_gm']);break;}$a=self::inspect($b);self::assertFalse($a['metadata']['available'],$c);self::assertSame([],$a['before']);self::assertSame([],$a['events']);}}
 public function testQueryHasClosedMandatoryParentWithoutWideningExistingEntities():void {$d=self::definition();self::assertTrue(RuntimeCiwErpQuery::supports($d));$q=RuntimeCiwErpQuery::prepare($d,self::endpoint('read'),['context'=>['proc_compra_id'=>17],'take'=>20,'skip'=>40]);self::assertSame(['skip'=>40,'take'=>20,'proc_compra_id'=>17],$q);$this->expectException(RuntimeHttpException::class);RuntimeCiwErpQuery::prepare($d,self::endpoint('read'),[]);}

 public static function ledger(int $type=3):array{return ['cta_corren_fornec_imp_id'=>91,'fornecedor_id'=>8,'item_proc_compra_id'=>12,'proc_compra_id'=>18,'data'=>'2026-10-22','historico'=>'Teste','cod_tipo_movto'=>$type,'vl_lancto'=>20.5,'cod_acao'=>3,'login'=>'real-user','data_hora'=>'2026-10-22T12:00:00.123','num_id_tit_ap'=>in_array($type,[4,5],true)?7:0,'item_container_id'=>in_array($type,[5,10],true)?71:0,'transacao_id'=>0];}
 public static function effect(array $after,string $resource='cta_corren_fornec_imp',string $operation='create',array $before=[]):array{return ['resource'=>$resource,'operation'=>$operation,'recordId'=>$after===[]?$before['cta_corren_fornec_imp_id']:$after[match($resource){'calcs_imp_container'=>'calc_imp_container_id','itens_container'=>'item_container_id',default=>'cta_corren_fornec_imp_id'}],'before'=>$before,'after'=>$after,'metadata'=>['originProcCompraId'=>17,'originItemProcCompraId'=>11]];}
 public function testFinancialEffectsRetainActualOwnersAndOriginForAllFourTypes():void{foreach([3,4,5,10]as $type){$b=self::body();$r=self::ledger($type);foreach([false,true]as $fiscal){if($fiscal)$r['container_id']=7;$b['audit']['changes']=[self::effect($r)];$a=self::inspect($b);self::assertTrue($a['metadata']['available']);self::assertSame($r,$a['events'][0]['after']);self::assertSame(18,$a['events'][0]['metadata']['procCompraId']);self::assertSame(17,$a['events'][0]['metadata']['originProcCompraId']);self::assertSame(12,$a['events'][0]['metadata']['itemProcCompraId']);self::assertSame(11,$a['events'][0]['metadata']['originItemProcCompraId']);if($fiscal){self::assertSame('container-panel-v1',$a['events'][0]['metadata']['scope']);}else{self::assertArrayNotHasKey('scope',$a['events'][0]['metadata']);}}}}
 public function testFinancialEffectsAreStrictAndAtomic():void{foreach(['delete','update','unknown','owner','origin','actor','action','type','transacao','title','container','legacy-action','duplicate','date','stamp']as $case){$b=self::body();$e=self::effect(self::ledger());switch($case){case 'delete':$e['operation']='delete';$e['before']=$e['after'];$e['after']=[];break;case 'update':$e['operation']='update';$e['before']=$e['after'];break;case 'unknown':$e['after']['free']=1;break;case 'owner':$e['after']['proc_compra_id']=0;break;case 'origin':$e['metadata']['originItemProcCompraId']=12;break;case 'actor':$e['after']['login']='browser';break;case 'action':$e['after']['cod_acao']=0;break;case 'type':$e['after']['cod_tipo_movto']=6;break;case 'transacao':$e['after']['transacao_id']=1;break;case 'title':$e['after']['cod_tipo_movto']=4;break;case 'container':$e['after']['item_container_id']=1;break;case 'legacy-action':$e['after']['cod_tipo_movto']=4;$e['after']['num_id_tit_ap']=7;$e['after']['item_container_id']=71;$e['after']['cod_acao']=1;break;case 'date':$e['after']['data']='2026-02-30';break;case 'stamp':$e['metadata']['row_stamp']='forged';break;}$b['audit']['changes']=[$e];if($case==='duplicate')$b['audit']['changes'][]=$e;$a=self::inspect($b);self::assertFalse($a['metadata']['available'],$case);self::assertSame([],$a['events']);}}
 public function testCompleteFiscalImagesAndChainedUpdatesAreImportedWithoutOmissions():void{$r=['container_id'=>7,'usuario_id'=>1,'memoria_calculo'=>0,'calc_imp_container_id'=>81,'dt_hr_calculo'=>null,'desc_memoria_calc'=>'Antes'];$b=self::body();$e=self::effect(array_replace($r,['desc_memoria_calc'=>'Depois']),'calcs_imp_container','update',$r);$b['audit']['changes']=[$e];$a=self::inspect($b);self::assertTrue($a['metadata']['available']);self::assertSame($r,$a['events'][0]['before']);self::assertSame(7,$a['events'][0]['metadata']['containerId']);self::assertSame(17,$a['events'][0]['metadata']['originProcCompraId']);self::assertArrayNotHasKey('procCompraId',$a['events'][0]['metadata']);$next=self::effect(array_replace($r,['desc_memoria_calc'=>'Final']),'calcs_imp_container','update',$e['after']);$b['audit']['changes'][]=$next;self::assertTrue(self::inspect($b)['metadata']['available']);$b['audit']['changes'][1]['before']=$r;self::assertFalse(self::inspect($b)['metadata']['available']);$b['audit']['changes']=[$e,$e];self::assertFalse(self::inspect($b)['metadata']['available']);unset($e['after']['usuario_id']);$b['audit']['changes']=[$e];self::assertFalse(self::inspect($b)['metadata']['available']);}
 public function testMalformedEffectTypesNeverThrowAfterCommit():void{foreach(['resource','operation','recordId']as $field){$b=self::body();$e=self::effect(['container_id'=>7,'usuario_id'=>1,'memoria_calculo'=>0,'calc_imp_container_id'=>81,'dt_hr_calculo'=>null,'desc_memoria_calc'=>'Teste'],'calcs_imp_container');$e[$field]=[];$b['audit']['changes']=[$e];self::assertFalse(self::inspect($b)['metadata']['available']);}}
 public function testFiscalAllocationKeepsItsActualPurchaseItemWithoutInventingTheParent():void{$r=['item_container_id'=>71,'container_id'=>7,'item_proc_compra_id'=>12,'cod_tipo_calculo'=>0,'qt_alocada'=>1,'qt_confirm_emb'=>0,'qt_recbto_fisico'=>0,'perc_custo'=>null,'perc_icms'=>null,'perc_ipi'=>null,'preco_liquida_ima'=>null,'log_rec_doc_prazo_emb'=>false,'log_calc_icms'=>true,'log_calc_ipi'=>false,'observacao'=>'Teste'];$b=self::body();$b['audit']['changes']=[self::effect(array_replace($r,['qt_alocada'=>2]),'itens_container','update',$r)];$a=self::inspect($b);self::assertTrue($a['metadata']['available']);self::assertSame(12,$a['events'][0]['metadata']['itemProcCompraId']);self::assertSame(11,$a['events'][0]['metadata']['originItemProcCompraId']);self::assertArrayNotHasKey('procCompraId',$a['events'][0]['metadata']);$b['audit']['changes'][0]['after']['item_proc_compra_id']=13;self::assertFalse(self::inspect($b)['metadata']['available']);}
}
